"""Self-contained local dashboard for the read-only stream watcher."""

from __future__ import annotations


PAGE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Driftline Live Watch</title>
<style>
:root{--ink:#edf7f4;--muted:#91aaa5;--panel:#102a2bde;--line:#28504d;--sea:#62e0c0;--gold:#f0c46b;--red:#ff8177;--bg:#061718}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% -10%,#194c48 0,transparent 35%),linear-gradient(145deg,#061718,#091e20 58%,#071414);color:var(--ink);font:15px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh}
.shell{max-width:1320px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:22px}.brand{display:flex;gap:14px;align-items:center}.mark{width:50px;height:50px;border:1px solid #4c8179;border-radius:15px;display:grid;place-items:center;background:#0d302f;font-size:25px;box-shadow:0 12px 35px #0008}.eyebrow{color:var(--sea);letter-spacing:.17em;font-size:11px;font-weight:750}.brand h1{margin:2px 0 0;font-size:25px;letter-spacing:-.03em}.pulse{display:flex;align-items:center;gap:9px;color:var(--sea);font-weight:700}.dot{width:10px;height:10px;border-radius:50%;background:var(--sea);box-shadow:0 0 0 0 #62e0c088;animation:pulse 1.8s infinite}@keyframes pulse{70%{box-shadow:0 0 0 10px #62e0c000}}
.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 18px 50px #0004;backdrop-filter:blur(12px)}.metric{grid-column:span 3}.metric.clickable{cursor:pointer;transition:.16s transform,.16s border-color}.metric.clickable:hover,.metric.clickable:focus{transform:translateY(-2px);border-color:var(--sea);outline:none}.metric.clickable .sub:after{content:'  →';color:var(--sea)}.metric .label,.section-title{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.12em;font-weight:750}.metric .value{font-size:28px;font-weight:780;margin-top:8px;letter-spacing:-.04em}.metric .sub{color:var(--muted);font-size:12px;margin-top:2px}.scanner{grid-column:span 9}.crypto-scanner{grid-column:span 12;border-color:#5d4e78}.events{grid-column:span 3}.sources{grid-column:span 12}.source-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.source{padding:12px;border-radius:12px;background:#0b2323;border:1px solid #1e4240}.source strong{display:block}.source span{color:var(--muted);font-size:11px}.source i{float:right;width:8px;height:8px;border-radius:50%;background:var(--sea);margin-top:6px}.source i.warn{background:var(--gold)}.safety{grid-column:span 12;display:flex;justify-content:space-between;align-items:center;gap:16px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.table-wrap{overflow:auto;max-height:480px}table{width:100%;border-collapse:collapse;white-space:nowrap}th{color:var(--muted);font-size:10px;text-align:right;padding:9px 7px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#102a2b}th:first-child,td:first-child{text-align:left}td{text-align:right;padding:10px 7px;border-bottom:1px solid #1c3b39;font-variant-numeric:tabular-nums;font-size:12px}.sym{font-weight:800;color:#fff}.up{color:var(--sea)}.down{color:var(--red)}.score{display:inline-grid;place-items:center;min-width:29px;height:25px;border-radius:8px;background:#173c39;color:var(--sea);font-weight:800}.status{text-align:left;max-width:210px}.status strong{display:block;font-size:10px}.status small{display:block;color:var(--muted);white-space:normal;line-height:1.25;margin-top:2px}.candidate strong{color:var(--sea)}.blocked strong{color:var(--red)}.tag{display:inline-block;padding:3px 8px;border-radius:99px;background:#173c39;color:#b9d8d1;font-size:10px;letter-spacing:.06em}.crypto-tag{background:#392d53;color:#d9c7ff}.stream{height:442px;overflow:auto}.event{border-left:2px solid var(--sea);padding:2px 0 14px 12px;margin:0 0 4px}.event.alert{border-color:var(--gold)}.event strong{font-size:13px}.event p{margin:3px 0;color:var(--muted);font-size:12px}.event time{color:#688681;font-size:10px}.empty{color:var(--muted);padding:35px 8px;text-align:center}.safe{display:flex;align-items:center;gap:12px}.shield{font-size:28px}.safe strong{display:block}.safe span{color:var(--muted);font-size:12px}button{border:1px solid #5b8e85;background:#143b38;color:white;border-radius:12px;padding:10px 14px;font-weight:750;cursor:pointer}button:hover{background:#1b4b47}button:disabled{opacity:.55}.stamp{color:var(--muted);font-size:12px}.error{color:var(--red)}.modal{position:fixed;inset:0;background:#020a0bd9;display:none;align-items:center;justify-content:center;padding:22px;z-index:20}.modal.open{display:flex}.modal-card{width:min(1050px,96vw);max-height:86vh;background:#0b2223;border:1px solid #3f6e68;border-radius:20px;padding:20px;box-shadow:0 30px 90px #000b;overflow:hidden}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.modal-head h2{margin:0;font-size:20px}.modal-body{max-height:68vh;overflow:auto}.close{font-size:20px;padding:5px 11px}.hint{color:var(--muted);font-size:12px;margin-top:4px}
@media(max-width:850px){.shell{padding:18px}.metric{grid-column:span 6}.scanner,.events,.sources{grid-column:span 12}.source-grid{grid-template-columns:repeat(2,1fr)}.top,.safety{align-items:flex-start;flex-direction:column}.stream{height:260px}}@media(max-width:480px){.metric{grid-column:span 12}.brand h1{font-size:21px}.source-grid{grid-template-columns:1fr}}
</style>
<style>
.options-scanner{grid-column:span 12;border-color:#756039}.options-tag{background:#493b20;color:#f4d58b}.backtest-scanner{grid-column:span 12;border-color:#397168}.backtest-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.backtest-stat{padding:13px;border-radius:12px;background:#0b2323;border:1px solid #1e4240}.backtest-stat small{display:block;color:var(--muted);font-size:10px;text-transform:uppercase}.backtest-stat strong{display:block;font-size:19px;margin-top:5px}.build{color:var(--muted);font-size:11px}@media(max-width:850px){.backtest-grid{grid-template-columns:repeat(2,1fr)}}
</style>
</head>
<body><main class="shell">
<header class="top"><div class="brand"><div class="mark">◉</div><div><div class="eyebrow">DRIFTLINE</div><h1>Live Market Watch</h1><div class="build" id="build">Checking version…</div></div></div><div id="connection" class="pulse"><i class="dot"></i><span>Connecting…</span></div></header>
<section class="grid">
<article class="card metric clickable" data-view="universe" role="button" tabindex="0"><div class="label">Symbols watched</div><div class="value" id="symbols">—</div><div class="sub">click for full universe</div></article>
<article class="card metric clickable" data-view="messages" role="button" tabindex="0"><div class="label">Market messages</div><div class="value" id="messages">—</div><div class="sub">click for message details</div></article>
<article class="card metric clickable" data-view="trades" role="button" tabindex="0"><div class="label">Trades inspected</div><div class="value" id="trades">—</div><div class="sub">click for recent trades</div></article>
<article class="card metric clickable" data-view="crypto" role="button" tabindex="0"><div class="label">Crypto watched</div><div class="value" id="cryptoSymbols">—</div><div class="sub">click for all pairs</div></article>
<article class="card metric clickable" data-view="options" role="button" tabindex="0"><div class="label">Option contracts</div><div class="value" id="optionContracts">—</div><div class="sub">click for volume details</div></article>
<article class="card metric clickable" data-view="backtest" role="button" tabindex="0"><div class="label">Backtest setups</div><div class="value" id="backtestSetups">—</div><div class="sub">click for learning results</div></article>
<article class="card metric"><div class="label">Alerts sent</div><div class="value" id="alerts">—</div><div class="sub">early heads-ups</div></article>
<article class="card scanner"><div class="section-head"><div><div class="section-title">Ranked intelligence scanner</div><div class="stamp" id="scanStamp">Waiting for market data…</div></div><span class="tag">AUTO REFRESH</span></div><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Score</th><th>Status / reason</th><th>Last</th><th>Trigger</th><th>VWAP</th><th>Distance</th><th>Day</th><th>15 sec</th><th>60 sec $</th><th>Est. RVOL</th><th>Spread</th></tr></thead><tbody id="rows"></tbody></table></div></article>
<article class="card events"><div class="section-head"><div><div class="section-title">Watcher activity</div><div class="stamp">What the program is doing</div></div></div><div class="stream" id="events"></div></article>
<article class="card crypto-scanner"><div class="section-head"><div><div class="section-title">24/7 crypto intelligence scanner</div><div class="stamp" id="cryptoStamp">Connecting to Alpaca crypto…</div></div><span class="tag crypto-tag">SEPARATE LIVE FEED</span></div><div class="table-wrap"><table><thead><tr><th>Pair</th><th>Score</th><th>Status / reason</th><th>Last</th><th>VWAP</th><th>Day</th><th>15 sec</th><th>60 sec $</th><th>Est. RVOL</th><th>Spread</th></tr></thead><tbody id="cryptoRows"></tbody></table></div></article>
<article class="card options-scanner"><div class="section-head"><div><div class="section-title">Options volume intelligence</div><div class="stamp" id="optionsStamp">Waiting for ranked stock candidates…</div></div><span class="tag options-tag">CONFIRMATION CONTEXT</span></div><div class="table-wrap"><table><thead><tr><th>Underlying</th><th>Status</th><th>Calls</th><th>Puts</th><th>Put / call</th><th>Volume / OI</th><th>Est. premium</th><th>Active contracts</th><th>Busiest contract</th></tr></thead><tbody id="optionRows"><tr><td colspan="9" class="empty">Building near-money option volume…</td></tr></tbody></table></div></article>
<article class="card backtest-scanner"><div class="section-head"><div><div class="section-title">Historical learning lab</div><div class="stamp" id="backtestStamp">Looking for the latest research report…</div></div><span class="tag">TRAINED ON PAST DATA</span></div><div class="backtest-grid"><div class="backtest-stat"><small>Tickers studied</small><strong id="btTickers">—</strong></div><div class="backtest-stat"><small>Setups replayed</small><strong id="btSetups">—</strong></div><div class="backtest-stat"><small>Average result</small><strong id="btAverage">—</strong></div><div class="backtest-stat"><small>Win rate</small><strong id="btWin">—</strong></div><div class="backtest-stat"><small>Paper-rule trades</small><strong id="btTrades">—</strong></div><div class="backtest-stat"><small>Unseen-data model</small><strong id="btModel">—</strong></div></div></article>
<article class="card sources"><div class="section-head"><div><div class="section-title">Source health</div><div class="stamp">What is connected and what remains optional</div></div></div><div class="source-grid" id="sources"></div></article>
<article class="card safety"><div class="safe"><div class="shield">🛡️</div><div><strong>READ ONLY — PAPER TRAINING</strong><span>No real or paper order can be placed, changed, or canceled from this program.</span></div></div><button id="test">Send safe test alert</button></article>
</section></main><div class="modal" id="modal" role="dialog" aria-modal="true"><div class="modal-card"><div class="modal-head"><div><h2 id="modalTitle">Details</h2><div class="hint" id="modalHint"></div></div><button class="close" id="close" aria-label="Close">×</button></div><div class="modal-body" id="modalBody"></div></div></div>
<script>
const $=id=>document.getElementById(id), fmt=n=>Number(n||0).toLocaleString(), money=n=>Number(n||0).toFixed(Number(n)<10?4:2), pct=n=>{n=Number(n||0);return `<span class="${n>=0?'up':'down'}">${n>=0?'+':''}${n.toFixed(2)}%</span>`}, val=(n,fn,blank='—')=>n===null||n===undefined||Number(n)===0?blank:fn(n);let latest={};
function age(iso){if(!iso)return 'No messages yet';let s=Math.max(0,Math.round((Date.now()-new Date(iso))/1000));return s<2?'just now':s<60?`${s}s ago`:`${Math.floor(s/60)}m ago`}
function table(head,rows){return `<table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`}
function openView(view){let title,hint,body,u=latest.universe||[],cu=latest.crypto_universe||[],m=latest.messages||[],tr=latest.trades||[],h=latest.health||{};if(view==='universe'){title='Complete stock universe';hint=`${u.length} stocks currently subscribed. Trigger is shown when today’s roster has a saved breakout level.`;body=table(['Symbol','Last','Bid','Ask','Previous close','Trigger'],u.map(s=>`<tr><td class="sym">${s.symbol}</td><td>${val(s.last,n=>'$'+money(n))}</td><td>${val(s.bid,n=>'$'+money(n))}</td><td>${val(s.ask,n=>'$'+money(n))}</td><td>${val(s.previous_close,n=>'$'+money(n))}</td><td>${val(s.trigger,n=>'$'+money(n))}</td></tr>`))}else if(view==='crypto'){title='Complete crypto universe';hint=`${cu.length} liquid USD pairs monitored around the clock on a separate Alpaca stream.`;body=table(['Pair','Last','Bid','Ask','Previous daily close'],cu.map(s=>`<tr><td class="sym">${s.symbol}</td><td>${val(s.last,n=>'$'+money(n))}</td><td>${val(s.bid,n=>'$'+money(n))}</td><td>${val(s.ask,n=>'$'+money(n))}</td><td>${val(s.previous_close,n=>'$'+money(n))}</td></tr>`))}else if(view==='messages'){title='Live market messages';hint=`${fmt(h.quote_count)} quotes · ${fmt(h.trade_count)} trades · ${fmt(h.other_message_count)} bars/status messages`;body=table(['Type','Market','Symbol','Received'],m.map(x=>`<tr><td>${x.type}</td><td>${x.asset_class||'stock'}</td><td class="sym">${x.symbol}</td><td>${new Date(x.timestamp).toLocaleTimeString()}</td></tr>`))}else{title='Recently inspected trades';hint='Live market prints examined by the early-warning engine. These are market events—not orders.';body=table(['Market','Symbol','Price','Size','Dollar value','Time'],tr.map(t=>`<tr><td>${t.asset_class||'stock'}</td><td class="sym">${t.symbol}</td><td>$${money(t.price)}</td><td>${fmt(t.size)}</td><td>$${fmt(Number(t.notional).toFixed(0))}</td><td>${new Date(t.timestamp).toLocaleTimeString()}</td></tr>`))}$('modalTitle').textContent=title;$('modalHint').textContent=hint;$('modalBody').innerHTML=body||'<div class="empty">No records yet.</div>';$('modal').classList.add('open')}
async function refresh(){try{let r=await fetch('/api/live',{cache:'no-store'}),d=await r.json(),h=d.health,c=$('connection'),crypto=d.crypto||[];latest=d;c.className=h.connected?'pulse':'pulse error';c.querySelector('span').textContent=h.connected?`Stocks connected · ${h.crypto_connected?'crypto connected':'crypto reconnecting'}`:'Stock feed disconnected · reconnecting';$('symbols').textContent=fmt(h.symbols);$('cryptoSymbols').textContent=fmt(h.crypto_symbols);$('messages').textContent=fmt(h.message_count);$('trades').textContent=fmt(h.trade_count);$('alerts').textContent=fmt(h.alert_count);$('scanStamp').textContent=`Ranked by live quality · message ${age(h.last_message_at)} · universe refreshed ${age(h.last_universe_refresh_at)}`;$('rows').innerHTML=d.symbols.length?d.symbols.map(s=>`<tr><td class="sym">${s.symbol}</td><td><span class="score">${s.score}</span></td><td class="status ${s.status_kind}"><strong>${s.status}</strong><small>${s.reason}</small></td><td>$${money(s.last)}</td><td>${val(s.trigger,n=>'$'+money(n))}</td><td>${val(s.rolling_vwap,n=>'$'+money(n))}</td><td>${s.trigger_distance_pct===null?'—':pct(s.trigger_distance_pct)}</td><td>${pct(s.day_move_pct)}</td><td>${pct(s.acceleration_pct)}</td><td>$${fmt(s.dollar_volume_60s.toFixed(0))}</td><td>${s.estimated_rvol===null?'—':Number(s.estimated_rvol).toFixed(2)+'×'}</td><td class="${s.spread_pct>0.4?'down':''}">${s.spread_pct>=999?'N/A':Number(s.spread_pct).toFixed(2)+'%'}</td></tr>`).join(''):`<tr><td colspan="12" class="empty">Connected and waiting for live stock trades.</td></tr>`;$('cryptoStamp').textContent=h.crypto_connected?`24/7 feed connected · ${fmt(h.crypto_symbols)} liquid pairs`:'Crypto stream reconnecting automatically';$('cryptoRows').innerHTML=crypto.length?crypto.map(s=>`<tr><td class="sym">${s.symbol}</td><td><span class="score">${s.score}</span></td><td class="status ${s.status_kind}"><strong>${s.status}</strong><small>${s.reason}</small></td><td>$${money(s.last)}</td><td>${val(s.rolling_vwap,n=>'$'+money(n))}</td><td>${pct(s.day_move_pct)}</td><td>${pct(s.acceleration_pct)}</td><td>$${fmt(s.dollar_volume_60s.toFixed(0))}</td><td>${s.estimated_rvol===null?'—':Number(s.estimated_rvol).toFixed(2)+'×'}</td><td class="${s.spread_pct>0.5?'down':''}">${s.spread_pct>=999?'N/A':Number(s.spread_pct).toFixed(2)+'%'}</td></tr>`).join(''):`<tr><td colspan="10" class="empty">Connecting to the separate 24/7 crypto feed and building live history.</td></tr>`;$('events').innerHTML=d.events.length?d.events.map(e=>`<div class="event ${e.kind==='alert'?'alert':''}"><strong>${e.title}</strong><p>${e.detail}</p><time>${new Date(e.timestamp).toLocaleTimeString()}</time></div>`).join(''):`<div class="empty">Startup activity will appear here.</div>`;$('sources').innerHTML=d.sources.map(s=>`<div class="source"><i class="${['live','ready','disabled'].includes(s.state)?'':'warn'}"></i><strong>${s.name}</strong><span>${s.state.toUpperCase()} · ${s.detail}</span></div>`).join('')}catch(e){$('connection').className='pulse error';$('connection').querySelector('span').textContent='Dashboard reconnecting…'}}
document.querySelectorAll('[data-view]').forEach(x=>{x.onclick=()=>openView(x.dataset.view);x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openView(x.dataset.view)}}});$('close').onclick=()=> $('modal').classList.remove('open');$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.remove('open')};document.onkeydown=e=>{if(e.key==='Escape')$('modal').classList.remove('open')};
$('test').onclick=async()=>{let b=$('test');b.disabled=true;b.textContent='Sending…';try{let r=await fetch('/api/test-alert',{method:'POST'}),d=await r.json();b.textContent=d.ok?'Test sent ✓':d.message||'Could not send'}catch(e){b.textContent='Could not send'}setTimeout(()=>{b.disabled=false;b.textContent='Send safe test alert'},4000);refresh()};refresh();setInterval(refresh,1500);
</script>
<script>
function optionBusy(o){let b=o&&o.busiest;if(!b||!b.symbol)return '—';return `${b.symbol} · ${fmt(b.volume)} vol / ${fmt(b.open_interest)} OI`}
function showOptions(){let rows=(latest.options||[]);$('modalTitle').textContent='Options volume details';$('modalHint').textContent='Near-money contracts for core indexes and leading stocks. Volume is activity—not proof that calls or puts were bought.';$('modalBody').innerHTML=rows.length?table(['Underlying','Contracts','Calls','Puts','Put/call','Call OI','Put OI','Volume/OI','Busiest'],rows.map(o=>`<tr><td class="sym">${o.symbol}</td><td>${fmt(o.contracts)}</td><td>${fmt(o.call_volume)}</td><td>${fmt(o.put_volume)}</td><td>${o.put_call_ratio===null?'—':Number(o.put_call_ratio).toFixed(2)}</td><td>${fmt(o.call_open_interest)}</td><td>${fmt(o.put_open_interest)}</td><td>${o.volume_oi===null?'—':Number(o.volume_oi).toFixed(2)+'×'}</td><td>${optionBusy(o)}</td></tr>`)):'<div class="empty">Options volume is still building or unavailable on the current data plan.</div>';$('modal').classList.add('open')}
let optionCard=document.querySelector('[data-view="options"]');if(optionCard){optionCard.onclick=showOptions;optionCard.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showOptions()}}}
function showBacktest(){let b=latest.backtest||{};$('modalTitle').textContent='Historical learning lab';$('modalHint').textContent=b.status==='ready'?`Last completed ${new Date(b.generated_at).toLocaleString()} · historical research only`:'The lab has not been run on this Mac yet.';if(b.status!=='ready'){$('modalBody').innerHTML='<div class="empty">Run <strong>Run Backtest Lab.command</strong> from the downloaded macOS folder. When it finishes, the results will appear here automatically.</div>'}else{let good=(b.promising||[]).map(x=>`<tr><td class="up">${x}</td></tr>`),bad=(b.avoid||[]).map(x=>`<tr><td class="down">${x}</td></tr>`);$('modalBody').innerHTML=`<div class="backtest-grid"><div class="backtest-stat"><small>Tickers</small><strong>${fmt(b.tickers)}</strong></div><div class="backtest-stat"><small>Setups</small><strong>${fmt(b.setups)}</strong></div><div class="backtest-stat"><small>Average</small><strong>${Number(b.average_r).toFixed(2)}R</strong></div><div class="backtest-stat"><small>Win rate</small><strong>${Number(b.win_rate).toFixed(1)}%</strong></div><div class="backtest-stat"><small>Paper trades</small><strong>${fmt(b.paper_trades)}</strong></div><div class="backtest-stat"><small>Model</small><strong>${b.model_status}</strong></div></div><h3>Promising on unseen days</h3>${good.length?table(['Pattern'],good):'<div class="empty">Nothing has earned this label yet.</div>'}<h3>Patterns to avoid</h3>${bad.length?table(['Pattern'],bad):'<div class="empty">Nothing has earned this label yet.</div>'}`}$('modal').classList.add('open')}
let backtestCard=document.querySelector('[data-view="backtest"]');if(backtestCard){backtestCard.onclick=showBacktest;backtestCard.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showBacktest()}}}
async function refreshOptions(){try{let r=await fetch('/api/live',{cache:'no-store'}),d=await r.json(),h=d.health||{},rows=d.options||[];latest=d;$('optionContracts').textContent=fmt(h.options_contracts);$('optionsStamp').textContent=h.options_status==='live'?`Session volume refreshed ${age(h.options_last_refresh_at)} · ${fmt(h.options_underlyings)} underlyings`:`Options volume ${h.options_status||'waiting'}; stock and crypto scanning continue`;$('optionRows').innerHTML=rows.length?rows.map(o=>`<tr><td class="sym">${o.symbol}<br><small>$${money(o.underlying_price)}</small></td><td class="status ${o.status_kind}"><strong>${o.status}</strong><small>${o.note}</small></td><td class="up">${fmt(o.call_volume)}</td><td class="down">${fmt(o.put_volume)}</td><td>${o.put_call_ratio===null?'—':Number(o.put_call_ratio).toFixed(2)}</td><td>${o.volume_oi===null?'—':Number(o.volume_oi).toFixed(2)+'×'}</td><td>$${fmt(Number(o.estimated_premium||0).toFixed(0))}</td><td>${fmt(o.active_contracts)} / ${fmt(o.contracts)}</td><td>${optionBusy(o)}</td></tr>`).join(''):`<tr><td colspan="9" class="empty">Building bounded near-money options volume. The watcher retries automatically if the data plan does not provide it.</td></tr>`}catch(e){$('optionsStamp').textContent='Options panel reconnecting…'}}
async function refreshBacktest(){try{let r=await fetch('/api/live',{cache:'no-store'}),d=await r.json(),b=d.backtest||{},h=d.health||{};latest=d;$('build').textContent=`Build ${h.build||'unknown'}`;$('backtestSetups').textContent=b.status==='ready'?fmt(b.setups):'NOT RUN';$('backtestStamp').textContent=b.status==='ready'?`Last completed ${new Date(b.generated_at).toLocaleString()} · click the Backtest setups card for patterns`:'Run “Run Backtest Lab.command” once; the finished results will appear here automatically.';$('btTickers').textContent=b.status==='ready'?fmt(b.tickers):'—';$('btSetups').textContent=b.status==='ready'?fmt(b.setups):'—';$('btAverage').textContent=b.status==='ready'?Number(b.average_r).toFixed(2)+'R':'—';$('btWin').textContent=b.status==='ready'?Number(b.win_rate).toFixed(1)+'%':'—';$('btTrades').textContent=b.status==='ready'?fmt(b.paper_trades):'—';$('btModel').textContent=b.status==='ready'?String(b.model_status).toUpperCase():'WAITING'}catch(e){$('backtestStamp').textContent='Backtest panel reconnecting…'}}
refreshOptions();refreshBacktest();setInterval(refreshOptions,3000);setInterval(refreshBacktest,5000);
</script></body></html>'''


